def explore(obj, prefix=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            print(f"{prefix}{key} -> {type(value)}")
            explore(value, prefix + '    ')
    elif isinstance(obj, list):
        for i, value in enumerate(obj):
            print(f"{prefix}[{i}] -> {type(value)}")
            explore(value, prefix + '    ')
    elif hasattr(obj, '__dict__'):
        for key, value in obj.__dict__.items():
            print(f"{prefix}{key} -> {type(value)}")
            explore(value, prefix + '    ')
    elif hasattr(obj, '_modules'):
        for key, value in obj._modules.items():
            print(f"{prefix}_modules[{key}] -> {type(value)}")
            explore(value, prefix + '    ')
    elif hasattr(obj, '_parameters'):
        for key, value in obj._parameters.items():
            print(f"{prefix}_parameters[{key}] -> {type(value)}")
            explore(value, prefix + '    ')
    elif hasattr(obj, '_buffers'):
        for key, value in obj._buffers.items():
            print(f"{prefix}_buffers[{key}] -> {type(value)}")
            explore(value, prefix + '    ')

print("Exploring Maze Object:")
explore(data)

